<script setup lang="ts">
import {ref} from 'vue'
import {useCareerStore} from '../stores/career'
const store=useCareerStore(),saved=ref(false)
async function save(){await store.saveProfile();saved.value=true;setTimeout(()=>saved.value=false,1800)}
</script>
<template><section class="workspace-page two-column"><div class="surface"><div class="surface-head"><div><p class="kicker">LONG-TERM MEMORY</p><h2>职业画像</h2></div><span class="status-chip">由你确认后写入</span></div><div class="field-grid"><label>学校<input v-model="store.profile.school" placeholder="你的学校"></label><label>专业<input v-model="store.profile.major"></label><label>年级<input v-model="store.profile.grade"></label><label>目标城市<input v-model="store.profile.targetCity"></label><label class="wide">目标岗位<input v-model="store.profile.targetPosition"></label><label class="wide">个人简介<textarea v-model="store.profile.selfDescription" rows="5" placeholder="技术方向、项目偏好和求职目标"></textarea></label></div><div class="form-actions"><span v-if="saved" class="success-text">✓ 已保存</span><button class="button" :disabled="store.loading" @click="save">保存画像</button></div></div><div class="surface"><div class="surface-head"><div><p class="kicker">EVIDENCE LEDGER</p><h2>技能证据</h2></div><b>{{store.skills.length}} 条</b></div><div v-if="store.skills.length" class="evidence-list"><article v-for="skill in store.skills" :key="skill.id"><div><strong>{{skill.name}}</strong><span>Lv.{{skill.level}}</span></div><p>{{skill.evidence}}</p><small>{{skill.source}} · {{skill.confirmed?'已确认':'待确认'}}</small></article></div><div v-else class="empty-state"><b>还没有经过确认的技能</b><p>上传简历并确认后，证据会出现在这里。</p><RouterLink to="/app/resumes">前往简历证据 ↗</RouterLink></div></div></section></template>
